from pathlib import Path;import subprocess,json;R=Path.cwd();H=Path.home();rp=R/'control/hourly/systemd/prediction-research-hourly-director.service';ip=H/'.config/systemd/user/prediction-research-hourly-director.service';out={};old='control/hourly/hourly_wake.py';new='control/hourly/hourly_cycle.py';[(lambda p:(p.exists() or (_ for _ in ()).throw(RuntimeError('missing '+str(p))),p.read_text(),p))(x) for x in [rp,ip]];rt=rp.read_text();it=ip.read_text();assert old in rt or new in rt;assert old in it or new in it;rp.write_text(rt.replace(old,new));ip.write_text(it.replace(old,new));dr=subprocess.run(['systemctl','--user','daemon-reload'],capture_output=True,text=True);st=subprocess.run(['systemctl','--user','start','prediction-research-hourly-director.service'],capture_output=True,text=True);tm=subprocess.run(['systemctl','--user','is-active','prediction-research-hourly-director.timer'],capture_output=True,text=True);sv=subprocess.run(['systemctl','--user','show','prediction-research-hourly-director.service','-p','ActiveState','-p','Result','--value'],capture_output=True,text=True);out={'daemon_reload':dr.returncode,'service_start':st.returncode,'timer_active':tm.stdout.strip(),'service_state':sv.stdout.strip().splitlines()};d=subprocess.run(['git','diff','--check'],capture_output=True,text=True);assert dr.returncode==0 and st.returncode==0 and d.returncode==0,(dr.stderr,st.stderr,d.stderr);subprocess.run(['git','add',str(rp)],capture_output=True,text=True);c=subprocess.run(['git','commit','-m','build(hourly): activate local autonomous cycle'],capture_output=True,text=True);p=subprocess.run(['git','push','origin','HEAD:main'],capture_output=True,text=True);out['commit_rc']=c.returncode;out['push_rc']=p.returncode;print(json.dumps(out,indent=2))